"""LLVM build helper generated by reflex generate web (no CMake)."""
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys

HERE = Path(__file__).resolve().parent
INITIAL_BYTES = 32 * 1024 * 1024
MAXIMUM_BYTES = 512 * 1024 * 1024
RSP_FORMAT_VERSION = 3


def argument_text(value):
    # Reflex manifests already use canonical strokes. Keep the same format for
    # filesystem paths constructed in Python; do not rewrite arbitrary options
    # or definitions, which can contain meaningful literal backslashes.
    return value.as_posix() if isinstance(value, Path) else str(value)


def run(command, cwd):
    arguments = [argument_text(arg) for arg in command]
    print(subprocess.list2cmdline(arguments), flush=True)
    subprocess.run(arguments, cwd=cwd, check=True)


def llvm_response_argument(value):
    # GNU response syntax is independent of shell/process quoting. Preserve
    # literal backslashes in definitions; paths have already been normalized.
    return '"' + argument_text(value).replace('\\', '\\\\').replace('"', '\\"') + '"'


def run_llvm(command, cwd, response):
    arguments = [llvm_response_argument(arg) for arg in command[1:]]
    response.write_text("\n".join(arguments) + "\n", encoding="utf-8")
    run([command[0], "@" + response.as_posix()], cwd)


def tool(name):
    llvm = os.environ.get("LLVM_ROOT")
    if llvm:
        candidate = Path(llvm) / "bin" / (name + (".exe" if os.name == "nt" else ""))
    else:
        candidate = shutil.which(name)
        if not candidate and os.name == "nt":
            candidate = Path(os.environ.get("LOCALAPPDATA", Path.home())) / "Programs/LLVM-23.1.1/LLVM/bin" / (name + ".exe")
    if not candidate or not Path(candidate).is_file():
        raise RuntimeError(f"Cannot find {name}; set LLVM_ROOT to your LLVM installation")
    return Path(candidate).absolute().as_posix()


def make_dependency_words(text):
    # Decode only Make escapes. A native Windows separator before an ordinary
    # filename character is not an escape (e.g. \reflex\core.cpp).
    words, word = [], []
    index = 0
    while index < len(text):
        char = text[index]
        if char == "\\" and index + 1 < len(text):
            following = text[index + 1]
            escaped = following in " \t#:" or (following == "\\" and os.name != "nt")
            if escaped:
                word.append(following)
                index += 2
                continue
        if char == "$" and index + 1 < len(text) and text[index + 1] == "$":
            word.append("$")
            index += 2
            continue
        if char.isspace():
            if word:
                words.append("".join(word))
                word = []
        else:
            word.append(char)
        index += 1
    if word:
        words.append("".join(word))
    return words


def dependency_paths(depfile, cwd):
    text = depfile.read_text(encoding="utf-8").replace("\\\n", " ")
    # Only the rule delimiter separates targets from dependencies; neither a
    # Windows drive colon nor an escaped colon within a filename does.
    rule = re.split(r"(?<!\\):(?:[ \t]|$)", text, maxsplit=1)
    if len(rule) != 2:
        raise ValueError(f"Malformed dependency file: {depfile}")
    words = make_dependency_words(rule[1])
    if not words:
        raise ValueError(f"Empty dependency file: {depfile}")
    # Normalize only decoded filesystem paths, after removing Make escapes.
    if os.name == "nt":
        words = [word.replace("\\", "/") for word in words]
    return [Path(cwd) / word for word in words]


def compile_source(source, obj, flags, compiler, cwd, rebuild):
    depfile = obj.with_suffix(".d")
    stamp = obj.with_suffix(".json")
    signature = json.dumps([RSP_FORMAT_VERSION, compiler, Path(compiler).stat().st_mtime_ns, flags, source])
    stale = rebuild or not obj.exists() or not depfile.exists() or not stamp.exists()
    if not stale:
        stale = stamp.read_text(encoding="utf-8") != signature
    if not stale:
        try:
            stale = any(not path.exists() or path.stat().st_mtime_ns > obj.stat().st_mtime_ns
                        for path in dependency_paths(depfile, cwd))
        except (ValueError, OSError):
            stale = True
    if stale:
        stamp.unlink(missing_ok=True)
        run_llvm([compiler, *flags, "-MMD", "-MF", depfile, "-c", source, "-o", obj], cwd, obj.with_suffix(".rsp"))
        stamp.write_text(signature, encoding="utf-8")
    return stale


def actions(items):
    # Execute every build: resource XML may refer to assets not listed as
    # explicit inputs. The resource builder itself avoids unchanged writes.
    for action in items:
        run(action["command"], action["cwd"])


def package(target, reflex):
    folder = Path(target["product"]).parent
    runtime = reflex / "resources/web"
    if not runtime.is_dir():
        raise RuntimeError(f"Browser runtime is missing: {runtime}")
    (folder / "runtime").mkdir(exist_ok=True)
    for source in runtime.glob("*.js"):
        shutil.copy2(source, folder / "runtime" / source.name)
    launcher = Path(target["launcher"])
    if not launcher.is_file():
        raise RuntimeError(f"Generated launcher is missing: {launcher}; regenerate the web project")
    shutil.copy2(launcher, folder / "index.html")


def main():
    manifest = json.loads((HERE / "build-config.json").read_text(encoding="utf-8"))
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--configuration", default=manifest["default_configuration"])
    parser.add_argument("--target", help="build one target and its dependencies")
    parser.add_argument("--jobs", type=int, default=os.cpu_count() or 1)
    parser.add_argument("--rebuild", action="store_true")
    args = parser.parse_args()
    if args.jobs < 1:
        parser.error("--jobs must be positive")
    targets = [target for target in manifest["targets"] if target["configuration"] == args.configuration]
    if not targets:
        parser.error(f"Undefined configuration: {args.configuration}")
    selected = [target for target in targets if not args.target or target["name"] == args.target]
    if not selected:
        parser.error(f"Undefined target for {args.configuration}: {args.target}")
    for builder in manifest["projects"]:
        if not Path(builder).is_file():
            raise RuntimeError(f"Missing generated dependency project: {builder}; regenerate web projects")
        command = [Path(sys.executable), builder, "--configuration", args.configuration, "--jobs", str(args.jobs)]
        if args.rebuild:
            command.append("--rebuild")
        run(command, HERE)
    compiler = tool("clang++")
    archiver = tool("llvm-ar")
    sysroot = os.environ.get("WASI_SYSROOT")
    if not sysroot and os.name == "nt":
        sysroot = (Path(os.environ.get("LOCALAPPDATA", Path.home())) / "Programs/ReflexWasm/wasi-sysroot-34.0").as_posix()
    if not sysroot or not Path(sysroot).is_dir():
        raise RuntimeError("Set WASI_SYSROOT to the threaded WASI SDK sysroot")
    sysroot = Path(sysroot).resolve().as_posix()
    common = ["--target=wasm32-wasip1-threads", "--sysroot=" + sysroot,
              "-isystem", (Path(sysroot) / "include/c++/v1").as_posix(), "-matomics", "-mbulk-memory",
              "-fwasm-exceptions", "-mllvm", "-wasm-enable-sjlj", "-mllvm", "-wasm-use-legacy-eh=false",
              "-Wno-invalid- offsetof".replace(" ", "")]
    reflex = Path(manifest["reflex"])
    # Preserve the explicit host import allowlist. Never permit
    # arbitrary missing Reflex symbols to become browser imports.
    # Keep resources/web/host-imports.txt aligned with gl.js and imports.js.
    allowlist = reflex / "resources/web/host-imports.txt"
    if not allowlist.is_file():
        raise RuntimeError(f"Browser host import allowlist is missing: {allowlist}")
    products = {Path(target["product"]).resolve().as_posix(): target for target in targets}
    completed, active = set(), set()

    def build(target):
        product = Path(target["product"])
        key = product.resolve().as_posix()
        if key in completed:
            return
        if key in active:
            raise RuntimeError(f"Dependency cycle at {product}")
        active.add(key)
        for library in dict.fromkeys([*target["dependencies"], *target["libraries"]]):
            dependency = products.get(Path(library).resolve().as_posix())
            if dependency:
                build(dependency)
            elif not library.startswith("-l") and not Path(library).is_file():
                raise RuntimeError(f"Missing library {library}; build its web source project first")
        actions(target["pre"])
        identity = hashlib.sha256(key.encode()).hexdigest()[:16]
        intermediate = HERE / "intermediate" / args.configuration / identity
        intermediate.mkdir(parents=True, exist_ok=True)
        flags = [*common, *target["flags"]]
        # clang++ otherwise treats .c files as C++, which rejects valid codec C.
        c_flags = [flag for flag in flags if not flag.startswith("-std=")
                   and flag not in ("-frtti", "-fno-rtti", "-fwasm-exceptions")]
        c_flags.extend(["-x", "c", "-std=c11"])
        objects = [intermediate / (str(index) + ".o") for index in range(len(target["sources"]))]
        with ThreadPoolExecutor(max_workers=args.jobs) as pool:
            jobs = [pool.submit(compile_source, source, obj,
                                c_flags if Path(source).suffix == ".c" else flags,
                                compiler, target["cwd"], args.rebuild)
                    for source, obj in zip(target["sources"], objects)]
            changed = any([job.result() for job in jobs])
        product.parent.mkdir(parents=True, exist_ok=True)
        if target["static"]:
            command = [archiver, "rcs", product, *objects]
        else:
            command = [compiler, *common, *objects, *target["libraries"],
                       "-lsetjmp", "-lunwind", "-mexec-model=reactor",
                       "-Wl,--allow-undefined-file=" + allowlist.as_posix(),
                       "-Wl,-z,stack-size=4194304,--export=malloc,--export=free,--export=__wasm_call_ctors,--import-memory",
                       f"-Wl,--initial-memory={INITIAL_BYTES},--max-memory={MAXIMUM_BYTES}", "-o", product]
            if args.configuration.casefold() == "release":
                command.append("-Wl,--strip-all")
        stamp = intermediate / "link.json"
        signature = json.dumps([RSP_FORMAT_VERSION, [argument_text(arg) for arg in command]])
        relink = args.rebuild or changed or not product.exists() or not stamp.exists()
        if not relink:
            relink = stamp.read_text(encoding="utf-8") != signature
        if not relink:
            inputs = [*objects, *[Path(lib) for lib in target["libraries"] if not lib.startswith("-l")]]
            if not target["static"]:
                inputs.append(allowlist)
            relink = any(path.stat().st_mtime_ns > product.stat().st_mtime_ns for path in inputs)
        if relink:
            stamp.unlink(missing_ok=True)
            # Recreate archives to remove objects from deleted source files.
            if target["static"]:
                product.unlink(missing_ok=True)
            run_llvm(command, target["cwd"], intermediate / "link.rsp")
            stamp.write_text(signature, encoding="utf-8")
        if not target["static"]:
            package(target, reflex)
        actions(target["post"])
        active.remove(key)
        completed.add(key)

    for target in selected:
        build(target)


if __name__ == "__main__":
    # Reflex's release macOS process launcher captures stdout but discards stderr.
    # Include Python and compiler diagnostics in the captured build output.
    os.dup2(sys.stdout.fileno(), sys.stderr.fileno())
    try:
        main()
    except (RuntimeError, OSError, subprocess.CalledProcessError) as error:
        print(f"Web build failed: {error}", file=sys.stderr)
        sys.exit(1)
